namespace sv_137a005354eb4a4e9e8b46686ac3c747.Components;

public enum ScreenCategory
{
    Mobile,
    Tablet,
    Desktop
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="CurrentScreenCategory" Name="ScreenSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    private ScreenCategory CurrentScreenCategory { get; set; } = ScreenCategory.Desktop;

    private IJSObjectReference? _module;
    private DotNetObjectReference<ScreenSizeProvider>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-137a005354eb4a4e9e8b46686ac3c747/screenSizeProvider.js");
            await _module.InvokeVoidAsync("initialize", _dotNetRef);
        }
    }

    [JSInvokable]
    public void OnViewportWidthChanged(int width)
    {
        var newCategory = width switch
        {
            < 768 => ScreenCategory.Mobile,
            < 1024 => ScreenCategory.Tablet,
            _ => ScreenCategory.Desktop
        };

        if (newCategory != CurrentScreenCategory)
        {
            CurrentScreenCategory = newCategory;
            StateHasChanged();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("dispose");
            await _module.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

let dotNetHelper = null;
let resizeHandler = null;

export function initialize(helper) {
    dotNetHelper = helper;

    resizeHandler = () => {
        dotNetHelper.invokeMethodAsync('OnViewportWidthChanged', window.innerWidth);
    };

    window.addEventListener('resize', resizeHandler);

    // Send the initial width immediately
    dotNetHelper.invokeMethodAsync('OnViewportWidthChanged', window.innerWidth);
}

export function dispose() {
    if (resizeHandler) {
        window.removeEventListener('resize', resizeHandler);
        resizeHandler = null;
    }
    dotNetHelper = null;
}

